/// <summary>
/// designed by AVANADE
/// </summary>
[ExtensionOf(classStr(Docu))]
final class AVADocuCls_Extension
{
}

Method.Source:
/// <summary>
/// designed by AVANADE
/// </summary>
/// <param name = "_from">Common</param>
/// <param name = "_to">Common</param>
server static void copyWithoutGAEB(Common _from, Common _to)
{
    DocuRef     docuRef;
    DocuRef     newDocuRef;
    DocuValue   docuValue;

    ttsbegin;

    while select docuRef
    index RefIdx
    where docuRef.RefCompanyId  == _from.DataAreaId &&
          docuRef.RefTableId    == _from.TableId    &&
          docuRef.RefRecId      == _from.RecId
    outer join docuValue
    where docuValue.RecId == docuRef.ValueRecId
    {
        if(docuValue.FileType != 'd93' && docuValue.FileType != 'd94')
        {
            newDocuRef.data(docuRef);
            newDocuRef.RefCompanyId  = _to.DataAreaId;
            newDocuRef.RefTableId    = _to.TableId;
            newDocuRef.RefRecId      = _to.RecId;
            newDocuRef.insert();
        }
    }

    ttscommit;
}

/// <summary>
/// Copies all document attachments from one record to another record.
/// </summary>
/// <param name = "_from">The source record</param>
/// <param name = "_to">The target record</param>
/// <param name="_filterByType">Optional. If provided, only documents of the provided DocuType will be copied.</param>
public static void copy(Common _from, Common _to, DocuTypeId _filterByType)
{
    next copy(_from,_to,_filterByType);

    AVADocuRestrictionReference         docuRestrictionReference;

    select firstonly docuRestrictionReference
        where docuRestrictionReference.DocuRefRecId == _to.RecId;

    if (!docuRestrictionReference && _to.RecId)
    {
        AVADocuRestriction          avaDocuRestriction;
        select firstonly avaDocuRestriction
            order by Num;
        docuRestrictionReference.DocuRefRecId = _to.RecId;
        docuRestrictionReference.DocuRestrictionNum = avaDocuRestriction.Num;
        docuRestrictionReference.insert();
    }


}
